post.description:
Persist SAML IdP configuration for *tenant_slug*.

Body (JSON)::

    {
      "idp_metadata_xml": "<full IdP metadata XML>",
      "jit_default_role": "viewer",
      "attribute_role_map": {"role": {"admin": "admin", ...}}
    }

Caller must hold ``sso.manage`` (Org Owner) for the matching tenant.

x-codeSamples.source:
import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const token = await client.tokens.issue({
  subjectAgentId: '<agent-uuid>',
  allowedActions: ['read'],
  allowedResources: ['s3://bucket/obj'],
  ttlSeconds: 300,
});
console.log(token.tokenId);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const child = await client.tokens.delegate('<parent-token-id>', {
  delegatingAgentId: '<agent-uuid>',
  subjectAgentId: '<child-agent-uuid>',
  allowedActions: ['read'],
  allowedResources: ['s3://bucket/obj'],
});
console.log(child.tokenId);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const result = await client.tokens.revoke('<token-id>', {
  reason: 'compromised',
  cascade: true,
});
console.log(result.revokedCount);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const env = await client.envelopes.create({
  workflowId: '<workflow-uuid>',
  agentId: '<agent-uuid>',
  actionType: 'retrieve',
  outputClassification: 'internal',
  capabilityTokenId: '<token-id>',
});
console.log(env.envelopeId, env.aggregationRiskScore);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const result = await client.envelopes.verify('<envelope-id>', {
  verifySignatures: true,
  verifyHashes: true,
  verifyClassification: true,
});
console.log(result.verificationResult);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const req = await client.envelopes.downgrade('<envelope-id>', {
  requestedClassification: 'internal',
  justification: 'Downgraded after PII redaction pass.',
});
console.log(req.downgradeRequestId);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const esc = await client.escalations.create({
  workflowId: '<workflow-uuid>',
  agentId: '<agent-uuid>',
  escalationType: 'policy_denial',
  attemptedAction: 'synthesize',
});
console.log(esc.escalationId);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const res = await client.escalations.resolve('<escalation-id>', {
  resolution: 'approved',
  notes: 'Reviewed and approved.',
});
console.log(res.issuedTokenId);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const result = await client.policies.evaluate({
  workflowId: '<workflow-uuid>',
  proposedAction: { actionType: 'synthesize' },
});
console.log(result.decision);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const policy = await client.policies.create({
  policyName: 'deny-synthesize-restricted',
  policyType: 'builtin',
  policyRules: { denyActions: ['synthesize'] },
});
console.log(policy.id);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const policy = await client.policies.update('<policy-id>', {
  status: 'disabled',
  priority: 10,
});
console.log(policy.version);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const ev = await client.integrity.recordEvent('<agent-uuid>', {
  eventType: 'boundary_violation',
  description: 'Agent attempted out-of-bounds action.',
});
console.log(ev.scoreBefore, ev.scoreAfter);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const res = await client.integrity.updateThresholds({
  suspendBelow: 40,
  requireEscalationBelow: 60,
});
console.log(res);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const result = await client.boundaries.check({
  agentId: '<agent-uuid>',
  workflowId: '<workflow-uuid>',
  proposedAction: { actionType: 'synthesize' },
});
console.log(result.decision);

import { MOSSClient } from '@moss/sdk';
const client = new MOSSClient({ apiKey: 'moss_live_...' });
const res = await client.boundaries.updateCapabilities('<agent-uuid>', {
  declaredCapabilities: { maxTokens: 5 },
  changeReason: 'reduced token budget',
});
console.log(res.constraintVersion);
